Map<String, List<({LatLng loc, double dir})>> targetPoints = {};
Map<String, int> timeRunningAnimation = {};
Map<String, Timer> animationTimers = {};
const animationSpeed = 0.02;
const rotAnimationSpeed = 0.1;
int animationRefreshRate = 80;

Future<void> updateSmoothPoints(
  String id,
  List<({LatLng loc, double dir})> locations,
  void Function(
    List<({LatLng loc, double dir})> newlocations,
  ) method,
) async {
  timeRunningAnimation[id] = 0;
  targetPoints[id] = locations;

  if (animationTimers[id] != null) {
    return;
  }

  animationTimers[id] = Timer.periodic(
    Duration(milliseconds: animationRefreshRate),
    (NAME_1) {
      timeRunningAnimation.update(
        id,
        (value) => value + animationRefreshRate,
        ifAbsent: () => 0,
      );
      final target = targetPoints[id];
      final currentPoints = listOfCurrentPoints[id];

      final newDats = List.generate(
        locations.length,
        (index) {
          final currentPoint = currentPoints?.elementAtOrNull(index);
          final targetPoint = target?.elementAtOrNull(index);

          final currentDir = currentPoint?.dir ?? locations[index].dir;
          var targetDir = targetPoint?.dir ?? locations[index].dir;

          var rotationDiff = (targetDir - currentDir) % 360;
          if (rotationDiff < 0) {
            rotationDiff += 360;
          }

          targetDir = rotationDiff > 180
              ? currentDir - (360 - rotationDiff)
              : currentDir + rotationDiff;

          return (
            loc: LatLng(
              lerpDouble(
                currentPoint?.loc.latitude ?? locations[index].loc.latitude,
                targetPoint?.loc.latitude ?? locations[index].loc.latitude,
                animationSpeed,
              )!,
              lerpDouble(
                currentPoint?.loc.longitude ?? locations[index].loc.longitude,
                targetPoint?.loc.longitude ?? locations[index].loc.longitude,
                animationSpeed,
              )!,
            ),
            dir: lerpDouble(currentDir, targetDir, rotAnimationSpeed)!,
          );
        },
      );

      listOfCurrentPoints[id] = newDats;
      method(newDats);

      if (timeRunningAnimation[id]! >= 4000) {
        animationTimers[id]?.cancel();
        animationTimers.remove(id);
        timeRunningAnimation[id] = 0;
      }
    },
  );
}

